import React, { useEffect, useState } from "react";
import { getFranchises, deleteFranchise } from "../services/api";
import { useNavigate } from "react-router-dom";
import { Box, Button, Typography, Card, CardContent } from "@mui/material";

const SuperAdminDashboard = () => {
    const [franchises, setFranchises] = useState([]);
    const navigate = useNavigate();

    const fetchFranchises = async () => {
        try {
            const { data } = await getFranchises();
            setFranchises(data);
        } catch (error) {
            console.error(error);
        }
    };

    const handleDelete = async (id) => {
        try {
            await deleteFranchise(id);
            fetchFranchises();
        } catch (error) {
            console.error(error);
        }
    };

    useEffect(() => {
        fetchFranchises();
    }, []);

    return (
        <Box padding={4}>
            <Typography variant="h4" gutterBottom>
                SuperAdmin Dashboard
            </Typography>
            <Button
                variant="contained"
                color="primary"
                onClick={() => navigate("/superadmin/add-exam-center")}
            >
                Add Exam Center
            </Button>
            <Box mt={4}>
                {franchises.map((franchise) => (
                    <Card key={franchise._id} style={{ marginBottom: "1rem" }}>
                        <CardContent>
                            <Typography variant="h6">{franchise.name}</Typography>
                            <Typography>{franchise.location}</Typography>
                            <Button
                                variant="contained"
                                color="secondary"
                                onClick={() => navigate(`/superadmin/view-exam-center/${franchise._id}`)}
                            >
                                View Details
                            </Button>
                            <Button
                                variant="contained"
                                color="error"
                                onClick={() => handleDelete(franchise._id)}
                            >
                                Delete
                            </Button>
                        </CardContent>
                    </Card>
                ))}
            </Box>
        </Box>
    );
};

export default SuperAdminDashboard;
